mapper.select:
        select FINPROD_MARKET_ID id, NVL(FINPROD_ABBR, FINPROD_NAME) text, FINPROD_ID object from FIN_PRODUCT


                and (instr(FINPROD_MARKET_ID, #{search}) > 0
                or instr(FINPROD_ID, #{search}) > 0
                or instr(FINPROD_NAME, #{search}) > 0
                or instr(FINPROD_ABBR, #{search}) > 0)


                and FINPROD_TYPE2 = #{finprodType2}


                and PROFIT_TYPE = #{profitType}


				AND FINPROD_MARKET_ID = #{initValue}

        select SEC_ACCT_ID id, SEC_ACCT_NAME text from STL_SEC_ACCT_INFO


                and (instr(SEC_ACCT_ID, #{search}) > 0 or instr(SEC_ACCT_NAME, #{search}) > 0)


				AND SEC_ACCT_ID = #{initValue}

