mapper.select:
SELECT psp.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, psp.SEC_ACCT_ID secAcctId, psp.AMOUNT regDateAmt, psp.CDATE regDate,
pp.INVEST_YESORNO investYesorno
from PTL_SEC_POSITION psp inner join FIN_PRODUCT fp on fp.FINPROD_ID = psp.FINPROD_ID inner join PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = psp.PORTFOLIO_ID WHERE nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null' and psp.CDATE = TO_DATE(#{regDate},'yyyy-MM-dd') AND psp.HODING_TYPE = #{POSITION_TYPE03} AND fp.FINPROD_MARKET_ID = #{finprodMarketId}
